    /// Optional. The member's primary vehicle, for their avatar badge: from their account at connect, updated when they change it. Null or absent when they have none or their account is private.
    var vehicle: GenWsServerRoomRoomMembersItemVehicle?
    var online: Bool
    var lastSeen: Int
    var position: GenWsServerRoomRoomMembersItemPosition?
}

struct GenWsServerRoomRoom: Codable, Equatable {
    var messages: [GenWsServerRoomRoomMessagesItem]
    /// Invite code, also the room id.
    var code: String
    var name: String
    var eventId: String?
    /// Additive in v1. Open convoy: Open Cruise drivers within 5 km see it and can join with cruise.join.
    var open: Bool?
    var leader: String
    var destination: GenWsServerRoomRoomDestination?
    var resting: Bool
    var route: GenWsServerRoomRoomRoute?
    /// Additive in v1, optional (absent when unknown). Road-following route from the leader to the destination, polyline with 6 decimals of precision, fetched by the server when the leader sets a destination while sharing a position. Dropped when the destination changes.
    var routeGeometry: String?
    var automaticRegroup: GenWsServerRoomRoomAutomaticRegroup
    var members: [GenWsServerRoomRoomMembersItem]
}

struct GenWsServerRoom: Codable, Equatable {
    var t: String
    var room: GenWsServerRoomRoom
}

struct GenWsServerLeft: Codable, Equatable {
    var t: String
    var room: String
    /// The leader put you out.
    var removed: Bool?
}

struct GenWsServerPos: Codable, Equatable {
    var t: String
    var room: String
    var id: String
    var lat: Double
    var lng: Double
    var heading: Double?
    var speed: Double?
    var ts: Int
}

struct GenWsServerError: Codable, Equatable {
    var t: String
    var error: String
    /// The 't' of the message that failed, when known.
    var `in`: String?
}

struct GenWsServerConvoyMessageMessage: Codable, Equatable {
    var id: String
    var clientId: String
    var userId: String
    var username: String
    var text: String
    var ts: Int
}

struct GenWsServerConvoyMessage: Codable, Equatable {
    var t: String
    var room: String
    var message: GenWsServerConvoyMessageMessage
}

struct GenWsServerHazardHazard: Codable, Equatable {
    var id: String
    var kind: GenJSON
    var subkind: String
    var lat: Double
    var lng: Double
    var heading: Double?
    var createdAt: String
    var expiresAt: String
}

/// Additive in v1. A member reported a hazard (POST /v1/hazards) while in this convoy; sent to every member of the room, including the reporter.
struct GenWsServerHazard: Codable, Equatable {
    var t: String
    var room: String
    var hazard: GenWsServerHazardHazard
}

/// Additive in v1. A notification for you (follow, comment, like, SOS, hazard), sent instead of a push while a socket is open. Apps keep a socket open in the background to get these without Google services. data.type names the kind.
struct GenWsServerNotify: Codable, Equatable {
    var t: String
    var title: String
    var body: String
    var data: [String: String]
}

/// Additive in v1. Your Open Cruise setting, after cruise.open.
struct GenWsServerCruiseState: Codable, Equatable {
    var t: String
    var on: Bool
}

struct GenWsServerCruiseNearbyDriversItemVehicleBuild: Codable, Equatable {
    /// #RRGGBB
    var paint: String?
    var finish: GenJSON?
    var wheel: String?
    var rideHeightMm: Int?
    var body: GenJSON?
    var shape: String?
}

struct GenWsServerCruiseNearbyDriversItemVehicle: Codable, Equatable {
    var kind: GenJSON
    var build: GenWsServerCruiseNearbyDriversItemVehicleBuild
}

struct GenWsServerCruiseNearbyDriversItem: Codable, Equatable {
    var id: String
    var username: String
    var avatar: String
    var vehicle: GenWsServerCruiseNearbyDriversItemVehicle?
    var lat: Double
    var lng: Double
    var distanceM: Double
    var canInvite: Bool
}

struct GenWsServerCruiseNearbyConvoysItem: Codable, Equatable {
    var code: String
    var name: String
    var members: Int
    var lat: Double
    var lng: Double
    var distanceM: Double
    var destination: String?
}

/// Additive in v1. Open Cruise: drivers (not in your convoy) and open convoys (not yours) within 5 km. Sent at most every 5 s while you move with Open Cruise on.
struct GenWsServerCruiseNearby: Codable, Equatable {
    var t: String
    var drivers: [GenWsServerCruiseNearbyDriversItem]
    var convoys: [GenWsServerCruiseNearbyConvoysItem]
}

/// Additive in v1. An Open Cruise driver nearby invited you. Answer with cruise.join before expiresAt.
struct GenWsServerCruiseInvite: Codable, Equatable {
    var t: String
    var from: String
    var fromName: String
    var code: String
    var name: String
    var expiresAt: Int
}

/// Additive in v1. Your invite was sent.
struct GenWsServerCruiseInvited: Codable, Equatable {
    var t: String
    var to: String
    var code: String
}

struct GenWsServerStatusPosition: Codable, Equatable {
    var lat: Double
    var lng: Double
    var heading: Double?
    var speed: Double?
    /// Server receive time, ms since the epoch.
    var ts: Int
}

/// Additive in v1. A member sent convoy.status; sent to every member of the room, including the sender. position is only present for sos: the sender's last known position, or null.
struct GenWsServerStatus: Codable, Equatable {
    var t: String
    var room: String
    /// Member id of the sender.
    var id: String
    var status: GenJSON
    var note: String?
    var position: GenWsServerStatusPosition?
}

/// The `t` values of the socket protocol.
enum GenWsType {
    static let clientPing: String = "ping"
    static let clientPosStop: String = "pos.stop"
    static let clientConvoyStatus: String = "convoy.status"
    static let clientPos: String = "pos"
    static let clientConvoyCreate: String = "convoy.create"
    static let clientConvoyJoin: String = "convoy.join"
    static let clientConvoyCruise: String = "convoy.cruise"
    static let clientConvoyLeave: String = "convoy.leave"
    static let clientConvoyDest: String = "convoy.dest"
    static let clientConvoyRename: String = "convoy.rename"
    static let clientConvoyRegroup: String = "convoy.regroup"
    static let clientConvoyRest: String = "convoy.rest"
    static let clientConvoyRoute: String = "convoy.route"
    static let clientConvoyLead: String = "convoy.lead"
    static let clientConvoyRemove: String = "convoy.remove"
    static let clientConvoyOpen: String = "convoy.open"
    static let clientCruiseOpen: String = "cruise.open"
    static let clientCruiseInvite: String = "cruise.invite"
    static let clientCruiseJoin: String = "cruise.join"
    static let clientConvoyMessage: String = "convoy.message"
    static let serverPong: String = "pong"
    static let serverHello: String = "hello"
    static let serverRoom: String = "room"
    static let serverLeft: String = "left"
    static let serverPos: String = "pos"
    static let serverError: String = "error"
    static let serverConvoyMessage: String = "convoy.message"
    static let serverHazard: String = "hazard"
    static let serverNotify: String = "notify"
    static let serverCruiseState: String = "cruise.state"
    static let serverCruiseNearby: String = "cruise.nearby"
    static let serverCruiseInvite: String = "cruise.invite"
    static let serverCruiseInvited: String = "cruise.invited"
    static let serverStatus: String = "status"
}
